/** Nav del usuario real, en el shape PLANO. Sin provider/sin sesión ⇒ `[]` (ARCH-1230: `DEFAULT_NAV`
 * es la proyección del rol default —un OPERADOR— y pintársela a un anónimo filtraba la IA del
 * back-office; ver `useRoleNav` del camino enriquecido para el argumento completo);
 * cargando ⇒ [] (nunca flash privilegiado); cero-match ⇒ [] + warn LOUD (fail-closed). */
export function useRoleNav(): NavGroup[] {
  const { identity, pending } = useIdentity();
  if (pending || identity === null) return [];
  const raw = identity.roles;
  const keys = normalizeUserRoles(raw);
  if (keys.length === 0) {
    warnUnmatchedRoles(raw);
    return [];
  }
  return computeNavForRoles(keys);
}
